(() => {
  "use strict";

  const Core = window.TextGameCore;
  const Model = window.AdventureAuthorModel;
  const ATTRS = ["str","end","vit","mnd","agi","dex","int"];
  const PRESETS = ["optimal_killer","self_preserving","dramatic_gm"];
  const ABILITY_KINDS = Model.ABILITY_KINDS;
  const ABILITY_TEMPLATES = {
    "Weak melee": {kind:"attack",ap:1,stamina:0,mana:0,power:30,minRange:0,maxRange:0,attackBonus:25,tags:["Physical"]},
    "Strong melee": {kind:"attack",ap:1,stamina:0,mana:0,power:55,minRange:0,maxRange:0,attackBonus:40,tags:["Physical"]},
    "Weak ranged": {kind:"attack",ap:1,stamina:0,mana:0,power:30,minRange:0,maxRange:1,attackBonus:25,tags:["Physical"]},
    "Strong ranged": {kind:"attack",ap:1,stamina:0,mana:0,power:55,minRange:0,maxRange:2,attackBonus:40,tags:["Physical"]},
    "Weak magic melee": {kind:"attack",ap:1,stamina:0,mana:2,power:35,minRange:0,maxRange:0,attackBonus:30,tags:["Magical"]},
    "Strong magic melee": {kind:"attack",ap:1,stamina:0,mana:2,power:60,minRange:0,maxRange:0,attackBonus:45,tags:["Magical"]},
    "Weak magic ranged": {kind:"attack",ap:1,stamina:0,mana:2,power:35,minRange:0,maxRange:1,attackBonus:30,tags:["Magical"]},
    "Strong magic ranged": {kind:"attack",ap:1,stamina:0,mana:2,power:60,minRange:0,maxRange:2,attackBonus:45,tags:["Magical"]},
    "Multi-target": {kind:"multi",ap:2,stamina:0,mana:0,power:40,minRange:0,maxRange:0,attackBonus:0,minTargets:2,maxTargets:3,tags:["Physical"]},
    "Push attack": {kind:"push",ap:1,stamina:0,mana:0,power:40,minRange:0,maxRange:0,attackBonus:35,tags:["Physical"]},
    "Persistent attack": {kind:"persistent",ap:2,stamina:0,mana:0,power:40,minRange:0,maxRange:0,attackBonus:35,condition:{id:"Persistent Damage",amount:10,expression:"Bleeding"},tags:["Physical"]}
  };

  const $ = s => document.querySelector(s);
  const canvas = $("#canvas"), edgesSvg = $("#edges"), inspector = $("#inspector");
  const fileLabel = $("#fileLabel");
  let adventure = null, selected = null, selectedChoice = null, fileHandle = null;
  let history = [], future = [], dragging = null, battleSceneId = null, battleSelectedZone = null, battleSubEditor = null;

  const clone = v => JSON.parse(JSON.stringify(v));
  const esc = v => String(v ?? "").replace(/[&<>"']/g, c => ({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#039;"}[c]));
  const slug = Model.slug;
  function unique(base, used){ let id=slug(base), n=2; while(used.has(id)) id=`${slug(base)}-${n++}`; return id; }
  function scenes(){ return adventure?.scenes || {}; }
  function nodePos(id,index=0){ const p=adventure?.editor?.nodes?.[id]; return p || {x:90+(index%4)*290,y:70+Math.floor(index/4)*190}; }
  function ensureEditor(){ adventure.editor ||= {}; adventure.editor.nodes ||= {}; }
  function checkpoint(){ if(!adventure)return; history.push(JSON.stringify(adventure)); if(history.length>100)history.shift(); future=[]; updateUndo(); }
  function mutate(fn){ if(!adventure)return; checkpoint(); fn(); render(); }
  function updateUndo(){ $("#undoBtn").disabled=!history.length; $("#redoBtn").disabled=!future.length; }
  function resetHistory(){ history=[]; future=[]; updateUndo(); }
  function syncBattlefieldAfterHistory(){
    const dialog=$("#battlefieldDialog");if(!dialog?.open)return;
    if(battleSceneId&&scenes()[battleSceneId])renderBattlefield();
    else{battleSceneId=null;battleSelectedZone=null;battleSubEditor=null;dialog.close();}
  }
  function undo(){ if(!history.length||!adventure)return; future.push(JSON.stringify(adventure)); adventure=JSON.parse(history.pop()); selected=null; selectedChoice=null; battleSubEditor=null; render(); syncBattlefieldAfterHistory(); updateUndo(); }
  function redo(){ if(!future.length||!adventure)return; history.push(JSON.stringify(adventure)); adventure=JSON.parse(future.pop()); selected=null; selectedChoice=null; battleSubEditor=null; render(); syncBattlefieldAfterHistory(); updateUndo(); }

  function newAdventure(id,title,days){
    adventure=Model.createAdventureDraft(id,title,days);
    fileHandle=null; selected="start"; selectedChoice=null; battleSubEditor=null; resetHistory(); render();
  }

  function knownTopFields(obj){ return Object.keys(obj).every(k=>["schemaVersion","kind","id","title","startScene","questDays","initialState","clocks","party","scenes","editor"].includes(k)); }
  function assertOpenable(obj){
    if(!obj||obj.kind!=="adventure")throw new Error("This file is not an adventure JSON file.");
    if(obj.schemaVersion!==2)throw new Error(`Adventure schema ${obj.schemaVersion ?? "unknown"} is not supported. The app or adventure schema may be out of date.`);
    if(!knownTopFields(obj))throw new Error("This adventure contains structural fields this version of Adventure Author does not understand. The app or adventure schema may be out of date.");
    const shapeIssues=Model.openableShapeIssues(obj);if(shapeIssues.length)throw new Error(`This adventure cannot be opened safely:\n${shapeIssues.join("\n")}`);
  }
  function normalizeLayout(){ ensureEditor(); let i=0; for(const id of Object.keys(scenes())) if(!adventure.editor.nodes[id])adventure.editor.nodes[id]=nodePos(id,i++); }

  async function openFile(){
    try{
      if(window.showOpenFilePicker){
        const [h]=await window.showOpenFilePicker({types:[{description:"Adventure JSON",accept:{"application/json":[".json"]}}],multiple:false});
        const f=await h.getFile(), obj=JSON.parse(await f.text()); assertOpenable(obj); adventure=obj; fileHandle=h; normalizeLayout(); selected=null; selectedChoice=null; battleSubEditor=null; resetHistory(); render(); return;
      }
    }catch(e){ if(e.name==="AbortError")return; alert(e.message); return; }
    $("#fallbackOpen").click();
  }
  $("#fallbackOpen").addEventListener("change",async e=>{ const f=e.target.files[0]; if(!f)return; try{const obj=JSON.parse(await f.text());assertOpenable(obj);adventure=obj;fileHandle=null;normalizeLayout();selected=null;selectedChoice=null;battleSubEditor=null;resetHistory();render();}catch(err){alert(err.message)} e.target.value=""; });
  async function saveFile(){
    if(!adventure)return; const text=JSON.stringify(adventure,null,2)+"\n";
    if(fileHandle){ try{const w=await fileHandle.createWritable();await w.write(text);await w.close();fileLabel.textContent=`${adventure.id}.json`;return;}catch(e){alert(`Could not overwrite the file: ${e.message}`);return;} }
    try{
      if(window.showSaveFilePicker){fileHandle=await window.showSaveFilePicker({suggestedName:`${adventure.id}.json`,types:[{description:"Adventure JSON",accept:{"application/json":[".json"]}}]});const w=await fileHandle.createWritable();await w.write(text);await w.close();fileLabel.textContent=`${adventure.id}.json`;return;}
    }catch(e){if(e.name==="AbortError")return;}
    const blob=new Blob([text],{type:"application/json"}),a=document.createElement("a");a.href=URL.createObjectURL(blob);a.download=`${adventure.id}.json`;a.click();URL.revokeObjectURL(a.href);alert("This browser cannot overwrite the original file directly. A new JSON file was downloaded instead.");
  }

  function outputsFor(scene){
    const out=[];
    if(scene.type==="scene") for(const c of scene.choices||[]){ if(c.resolution==="automatic")out.push({label:c.label||c.id,next:c.outcome?.next}); else if(c.resolution==="check"){out.push({label:`${c.label}: success`,next:c.success?.next});out.push({label:`${c.label}: failure`,next:c.failure?.next});out.push({label:`${c.label}: twist`,next:c.twist?.next});} }
    if(scene.type==="combat"){out.push({label:"Victory",next:scene.victory?.next});out.push({label:"Defeat",next:scene.defeat?.next});}
    return out;
  }
  function renderGraph(){
    canvas.innerHTML=""; edgesSvg.innerHTML=""; if(!adventure)return;
    const ids=Object.keys(scenes()); normalizeLayout();
    ids.forEach((id,i)=>{const s=scenes()[id],p=nodePos(id,i),el=document.createElement("div");el.className=`node ${s.type}${selected===id?" selected":""}`;el.dataset.id=id;el.style.left=`${p.x}px`;el.style.top=`${p.y}px`;const ports=outputsFor(s).map(o=>`<span class="port">${esc(o.label)}</span>`).join("");el.innerHTML=`<div class="node-head"><span>${esc(s.title||id)}</span><span class="node-id">${esc(id)}</span></div><div class="node-body">${s.type==="scene"?`${(s.text||[]).length} passages · ${(s.choices||[]).length} choices`:s.type==="combat"?`${(s.enemies||[]).length} enemies · ${(s.battlefield?.zones||[]).length} zones`:esc(s.outcome||"ending")}<div class="port-row">${ports}</div></div>`;el.addEventListener("mousedown",startDrag);el.addEventListener("click",e=>{e.stopPropagation();selected=id;selectedChoice=null;render();});canvas.appendChild(el);});
    requestAnimationFrame(renderEdges);
  }
  function renderEdges(){ edgesSvg.innerHTML=""; if(!adventure)return; for(const [from,s] of Object.entries(scenes())){const a=document.querySelector(`.node[data-id="${CSS.escape(from)}"]`);if(!a)continue;for(const o of outputsFor(s)){if(!o.next)continue;const b=document.querySelector(`.node[data-id="${CSS.escape(o.next)}"]`);if(!b)continue;const x1=a.offsetLeft+a.offsetWidth,y1=a.offsetTop+a.offsetHeight/2,x2=b.offsetLeft,y2=b.offsetTop+b.offsetHeight/2,c=Math.max(60,Math.abs(x2-x1)*.45);const path=document.createElementNS("http://www.w3.org/2000/svg","path");path.setAttribute("class","edge");path.setAttribute("d",`M${x1},${y1} C${x1+c},${y1} ${x2-c},${y2} ${x2},${y2}`);edgesSvg.appendChild(path);}}
  }
  function startDrag(e){ if(e.button!==0)return; const id=e.currentTarget.dataset.id,p=nodePos(id),sx=e.clientX,sy=e.clientY;dragging={id,sx,sy,x:p.x,y:p.y,moved:false};document.addEventListener("mousemove",dragMove);document.addEventListener("mouseup",dragEnd,{once:true}); }
  function dragMove(e){if(!dragging)return;const dx=e.clientX-dragging.sx,dy=e.clientY-dragging.sy;if(Math.abs(dx)+Math.abs(dy)>3)dragging.moved=true;ensureEditor();adventure.editor.nodes[dragging.id]={x:Math.max(0,dragging.x+dx),y:Math.max(0,dragging.y+dy)};const el=document.querySelector(`.node[data-id="${CSS.escape(dragging.id)}"]`);if(el){el.style.left=`${adventure.editor.nodes[dragging.id].x}px`;el.style.top=`${adventure.editor.nodes[dragging.id].y}px`;renderEdges();}}
  function dragEnd(){document.removeEventListener("mousemove",dragMove);if(dragging?.moved){history.push(JSON.stringify({...adventure,editor:{...adventure.editor,nodes:{...adventure.editor.nodes,[dragging.id]:{x:dragging.x,y:dragging.y}}}}));future=[];updateUndo();}dragging=null;}

  function optionsScenes(current=""){return Object.entries(scenes()).map(([id,s])=>`<option value="scene:${esc(id)}" ${id===current?"selected":""}>Scene · ${esc(id)} · ${esc(s.title)}</option>`).join("");}
  function outcomeDestinationValue(outcome){if(outcome?.next)return`scene:${outcome.next}`;if(outcome?.end)return`end:${outcome.end}`;return"";}
  function outcomeDestinationOptions(outcome){const current=outcomeDestinationValue(outcome);return `<option value="" ${current===""?"selected":""}>— unwired —</option><option value="end:victory" ${current==="end:victory"?"selected":""}>End · victory</option><option value="end:defeat" ${current==="end:defeat"?"selected":""}>End · defeat</option>`+optionsScenes(outcome?.next||"");}
  function field(label,value,key,type="text"){return `<label class="field"><span>${esc(label)}</span><input data-field="${esc(key)}" type="${type}" value="${esc(value)}"></label>`;}
  function bindFields(root,obj,onChange=()=>{}){ root.querySelectorAll("[data-field]").forEach(el=>el.addEventListener("change",()=>mutate(()=>{let v=el.type==="number"?Number(el.value):el.value;obj[el.dataset.field]=v;onChange();}))); }
  function effectEditor(effects=[]){const paths=statePaths();return `<div class="stack">${effects.map((ef,i)=>`<div class="card"><div class="row three"><select data-effect-type="${i}"><option ${ef.type==="set"?"selected":""}>set</option><option ${ef.type==="add"?"selected":""}>add</option><option value="advance-clock" ${ef.type==="advance-clock"?"selected":""}>advance-clock</option></select>${ef.type==="advance-clock"?`<select data-effect-clock="${i}">${Object.keys(adventure.clocks||{}).map(id=>`<option ${ef.id===id?"selected":""}>${esc(id)}</option>`)}</select><input data-effect-value="${i}" type="number" value="${esc(ef.segments??1)}">`:`<select data-effect-path="${i}">${paths.map(p=>`<option ${ef.path===p?"selected":""}>${esc(p)}</option>`)}</select><input data-effect-value="${i}" ${ef.type==="add"?'type="number" step="any"':''} value="${esc(ef.value ?? "")}">`}</div><button class="mini-btn danger" data-remove-effect="${i}">Remove</button></div>`).join("")}<button class="mini-btn" data-add-effect>Add effect</button></div>`;}
  function statePaths(){return ["quest.elapsedDays",...Object.keys(adventure.initialState?.flags||{}).map(k=>`flags.${k}`),...Object.keys(adventure.initialState?.counters||{}).map(k=>`counters.${k}`)];}
  function conditionPaths(){return [...statePaths(),...Object.keys(adventure.clocks||{}).map(id=>`clocks.${id}.filled`)];}
  function bindEffects(root,outcome){ outcome.effects ||= []; root.querySelector("[data-add-effect]")?.addEventListener("click",()=>mutate(()=>outcome.effects.push({type:"set",path:statePaths()[0]||"quest.elapsedDays",value:true})));root.querySelectorAll("[data-remove-effect]").forEach(b=>b.onclick=()=>mutate(()=>outcome.effects.splice(Number(b.dataset.removeEffect),1)));root.querySelectorAll("[data-effect-type]").forEach(el=>el.onchange=()=>mutate(()=>{const i=Number(el.dataset.effectType);outcome.effects[i]=el.value==="advance-clock"?{type:"advance-clock",id:Object.keys(adventure.clocks||{})[0]||"clock",segments:1}:{type:el.value,path:statePaths()[0]||"quest.elapsedDays",value:el.value==="add"?1:true};}));root.querySelectorAll("[data-effect-path]").forEach(el=>el.onchange=()=>mutate(()=>outcome.effects[Number(el.dataset.effectPath)].path=el.value));root.querySelectorAll("[data-effect-clock]").forEach(el=>el.onchange=()=>mutate(()=>outcome.effects[Number(el.dataset.effectClock)].id=el.value));root.querySelectorAll("[data-effect-value]").forEach(el=>el.onchange=()=>{const i=Number(el.dataset.effectValue),ef=outcome.effects[i],raw=el.value;if(ef.type==="add"){const parsed=Model.parseAddEffectValue(raw);if(!parsed.ok){alert(parsed.error);renderInspector();return;}mutate(()=>outcome.effects[i].value=parsed.value);return;}mutate(()=>{const current=outcome.effects[i];const val=raw==="true"?true:raw==="false"?false:(raw!==""&&!Number.isNaN(Number(raw))?Number(raw):raw);if(current.type==="advance-clock")current.segments=Number(raw)||0;else current.value=val;});}); }
  function outcomeEditor(name,outcome){return `<div class="section"><h3>${esc(name)}</h3><label class="field"><span>Text</span><textarea data-outcome-text>${esc(outcome.text||"")}</textarea></label><label class="field"><span>Destination</span><select data-outcome-next>${outcomeDestinationOptions(outcome)}</select></label><h4>Effects</h4>${effectEditor(outcome.effects||[])}</div>`;}
  function bindOutcome(root,outcome){root.querySelector("[data-outcome-text]").onchange=e=>mutate(()=>outcome.text=e.target.value);root.querySelector("[data-outcome-next]").onchange=e=>mutate(()=>{const value=e.target.value;delete outcome.next;delete outcome.end;if(value.startsWith("scene:"))outcome.next=value.slice(6);if(value.startsWith("end:"))outcome.end=value.slice(4);});bindEffects(root,outcome);}

  function renderSceneInspector(id,s){
    if(selectedChoice!=null)return renderChoiceInspector(id,s,selectedChoice);
    inspector.innerHTML=`<h2>Scene</h2>${field("ID",id,"__id")}${field("Title",s.title,"title")}<div class="section"><div class="section-title"><h3>Passages</h3><div><button class="mini-btn" id="addNarration">+ Narration</button> <button class="mini-btn" id="addDialogue">+ Dialogue</button></div></div><div class="stack">${(s.text||[]).map((p,i)=>typeof p==="string"?`<div class="card"><div class="card-title"><span>Narration</span><span><button data-up-pass="${i}">↑</button><button data-down-pass="${i}">↓</button><button data-del-pass="${i}">×</button></span></div><textarea data-pass-text="${i}">${esc(p)}</textarea></div>`:`<div class="card"><div class="card-title"><span>Dialogue</span><span><button data-up-pass="${i}">↑</button><button data-down-pass="${i}">↓</button><button data-del-pass="${i}">×</button></span></div><input data-pass-speaker="${i}" value="${esc(p.speaker)}" placeholder="Speaker"><textarea data-pass-text="${i}">${esc(p.text)}</textarea></div>`).join("")}</div></div><div class="section"><div class="section-title"><h3>Choices</h3><div><button class="mini-btn" id="addAutomatic">+ Automatic</button> <button class="mini-btn" id="addCheck">+ Check</button></div></div><div class="stack">${(s.choices||[]).map((c,i)=>`<button data-choice="${i}">${esc(c.label||c.id)} <span class="badge">${esc(c.resolution)}</span></button>`).join("")||'<span class="muted">No choices yet.</span>'}</div></div><button class="danger" id="deleteNode">Delete scene</button>`;
    inspector.querySelector('[data-field="title"]').onchange=e=>mutate(()=>s.title=e.target.value);
    inspector.querySelector('[data-field="__id"]').onchange=e=>renameScene(id,e.target.value);
    $("#addNarration").onclick=()=>mutate(()=>{s.text ||= [];s.text.push("New narration.")});$("#addDialogue").onclick=()=>mutate(()=>{s.text ||= [];s.text.push({speaker:"Speaker",text:"New dialogue."})});
    inspector.querySelectorAll("[data-pass-text]").forEach(el=>el.onchange=()=>mutate(()=>{const i=Number(el.dataset.passText);if(typeof s.text[i]==="string")s.text[i]=el.value;else s.text[i].text=el.value;}));inspector.querySelectorAll("[data-pass-speaker]").forEach(el=>el.onchange=()=>mutate(()=>s.text[Number(el.dataset.passSpeaker)].speaker=el.value));
    inspector.querySelectorAll("[data-del-pass]").forEach(b=>b.onclick=()=>mutate(()=>s.text.splice(Number(b.dataset.delPass),1)));inspector.querySelectorAll("[data-up-pass]").forEach(b=>b.onclick=()=>mutate(()=>moveItem(s.text,Number(b.dataset.upPass),-1)));inspector.querySelectorAll("[data-down-pass]").forEach(b=>b.onclick=()=>mutate(()=>moveItem(s.text,Number(b.dataset.downPass),1)));
    inspector.querySelectorAll("[data-choice]").forEach(b=>b.onclick=()=>{selectedChoice=Number(b.dataset.choice);renderInspector();});
    $("#addAutomatic").onclick=()=>mutate(()=>{s.choices ||= [];const uid=unique("choice",new Set(s.choices.map(x=>x.id)));s.choices.push({id:uid,label:"New choice",resolution:"automatic",reason:"No roll is required.",outcome:{text:"Describe what happens.",next:""}});selectedChoice=s.choices.length-1;});
    $("#addCheck").onclick=()=>mutate(()=>{s.choices ||= [];const uid=unique("check",new Set(s.choices.map(x=>x.id)));s.choices.push({id:uid,label:"Attempt a challenge",resolution:"check",actor:{mode:"select",eligible:["*"]},check:{goal:"State the goal.",approach:"State the approach.",baseTN:40,attributes:["int","dex"],skill:"Awareness",situationalModifiers:[]},success:{text:"The goal succeeds.",next:""},failure:{text:"The goal fails and the situation changes.",next:""},twistPreview:"The goal succeeds, but there is a complication.",twist:{text:"The goal succeeds with a complication.",next:""}});selectedChoice=s.choices.length-1;});
    $("#deleteNode").onclick=()=>deleteNode(id);
  }
  function moveItem(a,i,d){const j=i+d;if(j<0||j>=a.length)return;[a[i],a[j]]=[a[j],a[i]];}

  function conditionShape(when){
    if(!when)return{mode:"all",conditions:[]};
    if(Array.isArray(when))return{mode:"array",conditions:when};
    if(Array.isArray(when.all))return{mode:"all",conditions:when.all};
    if(Array.isArray(when.any))return{mode:"any",conditions:when.any};
    return{mode:"direct",conditions:[when]};
  }
  function setConditionMode(choice,mode){
    const {conditions}=conditionShape(choice.when),items=conditions.length?conditions:[{path:conditionPaths()[0]||"quest.elapsedDays",equals:true}];
    if(mode==="direct")choice.when=clone(items[0]);
    else choice.when={[mode]:items.map(clone)};
  }
  function conditionAt(choice,index){return conditionShape(choice.when).conditions[index];}
  function whenEditor(when){
    const shape=conditionShape(when),mode=shape.mode==="array"?"all":shape.mode,conds=shape.conditions;
    return `<div class="section"><div class="section-title"><h3>Visibility</h3><button class="mini-btn" data-add-condition>+ Condition</button></div><label class="field"><span>Condition mode</span><select data-when-mode><option value="direct" ${mode==="direct"?"selected":""}>Direct</option><option value="all" ${mode==="all"?"selected":""}>All</option><option value="any" ${mode==="any"?"selected":""}>Any</option></select></label>${conds.map((c,i)=>`<div class="row three"><select data-cond-path="${i}">${conditionPaths().map(p=>`<option ${c.path===p?"selected":""}>${esc(p)}</option>`)}</select><select data-cond-op="${i}">${["equals","notEquals","gte","lte"].map(op=>`<option ${c[op]!==undefined?"selected":""}>${op}</option>`)}</select><input data-cond-val="${i}" value="${esc(c.equals??c.notEquals??c.gte??c.lte??"")}"></div><button class="mini-btn danger" data-del-condition="${i}">Remove</button>`).join("")||'<p class="hint">Always visible.</p>'}</div>`;
  }
  function bindWhen(root,c){
    root.querySelector("[data-when-mode]").onchange=e=>mutate(()=>setConditionMode(c,e.target.value));
    root.querySelector("[data-add-condition]").onclick=()=>mutate(()=>{const next={path:conditionPaths()[0]||"quest.elapsedDays",equals:true},shape=conditionShape(c.when);if(!c.when)c.when={all:[next]};else if(shape.mode==="direct")c.when={all:[clone(shape.conditions[0]),next]};else if(shape.mode==="array")c.when.push(next);else c.when[shape.mode].push(next);});
    root.querySelectorAll("[data-del-condition]").forEach(b=>b.onclick=()=>mutate(()=>{const shape=conditionShape(c.when),i=Number(b.dataset.delCondition);if(shape.mode==="direct")delete c.when;else{shape.conditions.splice(i,1);if(!shape.conditions.length)delete c.when;}}));
    root.querySelectorAll("[data-cond-path]").forEach(el=>el.onchange=()=>mutate(()=>conditionAt(c,Number(el.dataset.condPath)).path=el.value));
    root.querySelectorAll("[data-cond-op]").forEach(el=>el.onchange=()=>mutate(()=>{const x=conditionAt(c,Number(el.dataset.condOp)),v=x.equals??x.notEquals??x.gte??x.lte;for(const k of ["equals","notEquals","gte","lte"])delete x[k];x[el.value]=v;}));
    root.querySelectorAll("[data-cond-val]").forEach(el=>el.onchange=()=>mutate(()=>{const x=conditionAt(c,Number(el.dataset.condVal)),op=["equals","notEquals","gte","lte"].find(k=>x[k]!==undefined),r=el.value;x[op]=r==="true"?true:r==="false"?false:(r!==""&&!Number.isNaN(Number(r))?Number(r):r);}));
  }
  function selectableActorEditor(actor){const eligible=Array.isArray(actor?.eligible)?actor.eligible:["*"];const all=eligible.includes("*");const actors=[{id:"$main",name:"$main"},...(adventure.party||[]).map(p=>({id:p.id,name:p.name}))];return `<label class="field"><span>Eligible actors</span><select id="eligibleMode"><option value="all" ${all?"selected":""}>Whole party (*)</option><option value="specific" ${!all?"selected":""}>Specific actors</option></select></label>${all?'<p class="hint">Any party member may attempt this check.</p>':`<div class="stack">${actors.map(a=>`<label><input type="checkbox" data-eligible-actor="${esc(a.id)}" ${eligible.includes(a.id)?"checked":""}> ${esc(a.name)} <span class="muted">${esc(a.id)}</span></label>`).join("")}</div>`}`;}
  function bindSelectableActor(root,c){const mode=root.querySelector("#eligibleMode");if(!mode)return;mode.onchange=e=>mutate(()=>{c.actor.eligible=e.target.value==="all"?["*"]:["$main"]});root.querySelectorAll("[data-eligible-actor]").forEach(el=>el.onchange=()=>mutate(()=>{const ids=[...root.querySelectorAll("[data-eligible-actor]:checked")].map(x=>x.dataset.eligibleActor);c.actor.eligible=ids.length?ids:["$main"];}));}
  function renderChoiceInspector(id,s,i){
    const c=s.choices[i];if(!c){selectedChoice=null;return renderSceneInspector(id,s)}
    c.check && (c.check.situationalModifiers ||= []);
    const modifiers=c.check?.situationalModifiers||[];
    let body=`<button id="backChoice">← Scene</button><h2>Choice</h2>${field("ID",c.id,"id")}${field("Label",c.label,"label")}<label class="field"><span>Description</span><textarea data-choice-desc>${esc(c.description||"")}</textarea></label>${whenEditor(c.when)}`;
    if(c.resolution==="automatic")body+=`${field("Reason",c.reason||"","reason")}${outcomeEditor("Outcome",c.outcome)}`;
    else body+=`<div class="section"><h3>Check</h3><label class="field"><span>Actor mode</span><select id="actorMode"><option value="select" ${c.actor?.mode==="select"?"selected":""}>Selectable</option><option value="fixed" ${c.actor?.mode==="fixed"?"selected":""}>Fixed</option></select></label>${c.actor?.mode==="fixed"?`<label class="field"><span>Actor</span><select id="fixedActor"><option value="$main">$main</option>${(adventure.party||[]).map(p=>`<option value="${esc(p.id)}" ${c.actor.id===p.id?"selected":""}>${esc(p.name)}</option>`)}</select></label>`:selectableActorEditor(c.actor)}${field("Goal",c.check.goal||"","goal")}${field("Approach",c.check.approach||"","approach")}${field("Base TN",c.check.baseTN,"baseTN","number")}<div class="row"><label class="field"><span>Attribute 1</span><select id="attr1">${ATTRS.map(a=>`<option ${c.check.attributes?.[0]===a?"selected":""}>${a}</option>`)}</select></label><label class="field"><span>Attribute 2</span><select id="attr2">${ATTRS.map(a=>`<option ${c.check.attributes?.[1]===a?"selected":""}>${a}</option>`)}</select></label></div>${field("Skill",c.check.skill||"","skill")}<label class="field"><span>Clock</span><select id="checkClock"><option value="">None</option>${Object.keys(adventure.clocks||{}).map(k=>`<option ${c.check.clock===k?"selected":""}>${esc(k)}</option>`)}</select></label><div class="section-title"><h4>Situational modifiers</h4><button id="addSituationalModifier" class="mini-btn">+ Modifier</button></div><div class="stack">${modifiers.map((m,j)=>`<div class="row three"><input data-mod-label="${j}" value="${esc(m.label||"")}" placeholder="Label"><input data-mod-value="${j}" type="number" value="${esc(m.value??0)}"><button data-del-mod="${j}" class="mini-btn danger">Remove</button></div>`).join("")||'<p class="hint">No situational modifiers.</p>'}</div></div>${outcomeEditor("Success",c.success)}${outcomeEditor("Failure",c.failure)}${field("Twist preview",c.twistPreview||"","twistPreview")}${outcomeEditor("Twist",c.twist)}`;
    body+=`<button class="danger" id="deleteChoice">Delete choice</button>`; inspector.innerHTML=body;$("#backChoice").onclick=()=>{selectedChoice=null;renderInspector()};inspector.querySelector('[data-field="id"]').onchange=e=>{const preview=Model.renameChoiceId(clone(s),i,e.target.value);if(!preview.ok){alert(preview.error);renderChoiceInspector(id,s,i);return;}if(preview.changed)mutate(()=>Model.renameChoiceId(s,i,e.target.value));};inspector.querySelector('[data-field="label"]').onchange=e=>mutate(()=>c.label=e.target.value);inspector.querySelector('[data-choice-desc]').onchange=e=>mutate(()=>c.description=e.target.value);bindWhen(inspector,c);
    if(c.resolution==="automatic"){inspector.querySelector('[data-field="reason"]').onchange=e=>mutate(()=>c.reason=e.target.value);bindOutcome(inspector.querySelectorAll(".section")[1],c.outcome);}else{
      $("#actorMode").onchange=e=>mutate(()=>c.actor=e.target.value==="fixed"?{mode:"fixed",id:"$main"}:{mode:"select",eligible:["*"]});$("#fixedActor")&&($("#fixedActor").onchange=e=>mutate(()=>c.actor.id=e.target.value));bindSelectableActor(inspector,c);for(const k of ["goal","approach","baseTN","skill"])inspector.querySelector(`[data-field="${k}"]`).onchange=e=>mutate(()=>c.check[k]=k==="baseTN"?Number(e.target.value):e.target.value);$("#attr1").onchange=e=>mutate(()=>c.check.attributes[0]=e.target.value);$("#attr2").onchange=e=>mutate(()=>c.check.attributes[1]=e.target.value);$("#checkClock").onchange=e=>mutate(()=>{if(e.target.value)c.check.clock=e.target.value;else delete c.check.clock;});$("#addSituationalModifier").onclick=()=>mutate(()=>c.check.situationalModifiers.push({label:"New modifier",value:5}));inspector.querySelectorAll("[data-mod-label]").forEach(el=>el.onchange=()=>mutate(()=>c.check.situationalModifiers[Number(el.dataset.modLabel)].label=el.value));inspector.querySelectorAll("[data-mod-value]").forEach(el=>el.onchange=()=>mutate(()=>c.check.situationalModifiers[Number(el.dataset.modValue)].value=Number(el.value)));inspector.querySelectorAll("[data-del-mod]").forEach(el=>el.onclick=()=>mutate(()=>c.check.situationalModifiers.splice(Number(el.dataset.delMod),1)));inspector.querySelector('[data-field="twistPreview"]').onchange=e=>mutate(()=>c.twistPreview=e.target.value);const outs=inspector.querySelectorAll(".section");bindOutcome(outs[2],c.success);bindOutcome(outs[3],c.failure);bindOutcome(outs[4],c.twist);
    }$("#deleteChoice").onclick=()=>mutate(()=>{s.choices.splice(i,1);selectedChoice=null;});
  }

  function renderCombatInspector(id,s){s.battlefield ||= {zones:[],links:[]};s.pcStarts ||= {};s.enemies ||= [];s.victory ||= {text:"Victory.",next:""};s.defeat ||= {text:"Defeat.",next:""};inspector.innerHTML=`<h2>Combat</h2>${field("ID",id,"__id")}${field("Title",s.title,"title")}<label class="field"><span>Ambush</span><select id="ambush"><option value="false" ${!s.ambush?"selected":""}>No</option><option value="true" ${s.ambush?"selected":""}>Yes</option></select></label><button id="editBattlefield">Edit Battlefield</button>${outcomeEditor("Victory",s.victory)}${outcomeEditor("Defeat",s.defeat)}<button class="danger" id="deleteNode">Delete combat</button>`;inspector.querySelector('[data-field="title"]').onchange=e=>mutate(()=>s.title=e.target.value);inspector.querySelector('[data-field="__id"]').onchange=e=>renameScene(id,e.target.value);$("#ambush").onchange=e=>mutate(()=>s.ambush=e.target.value==="true");$("#editBattlefield").onclick=()=>openBattlefield(id);const sec=inspector.querySelectorAll(".section");bindOutcome(sec[0],s.victory);bindOutcome(sec[1],s.defeat);$("#deleteNode").onclick=()=>deleteNode(id);}
  function renderEndingInspector(id,s){inspector.innerHTML=`<h2>Ending</h2>${field("ID",id,"__id")}${field("Title",s.title,"title")}<label class="field"><span>Outcome</span><select id="endingOutcome"><option ${s.outcome==="victory"?"selected":""}>victory</option><option ${s.outcome==="defeat"?"selected":""}>defeat</option></select></label><label class="field"><span>Text</span><textarea id="endingText">${esc(s.text||"")}</textarea></label><button class="danger" id="deleteNode">Delete ending</button>`;inspector.querySelector('[data-field="title"]').onchange=e=>mutate(()=>s.title=e.target.value);inspector.querySelector('[data-field="__id"]').onchange=e=>renameScene(id,e.target.value);$("#endingOutcome").onchange=e=>mutate(()=>s.outcome=e.target.value);$("#endingText").onchange=e=>mutate(()=>s.text=e.target.value);$("#deleteNode").onclick=()=>deleteNode(id);}
  function renderInspector(){if(!adventure){inspector.innerHTML='<div class="empty-state">Create or open an adventure.</div>';return}if(!selected||!scenes()[selected]){renderMeta();return}const s=scenes()[selected];if(s.type==="scene")renderSceneInspector(selected,s);if(s.type==="combat")renderCombatInspector(selected,s);if(s.type==="ending")renderEndingInspector(selected,s);}

  function renameScene(oldId,newRaw){const id=slug(newRaw);if(id===oldId)return;if(scenes()[id]){alert("That scene id already exists.");renderInspector();return}mutate(()=>{scenes()[id]=scenes()[oldId];delete scenes()[oldId];if(adventure.startScene===oldId)adventure.startScene=id;ensureEditor();adventure.editor.nodes[id]=adventure.editor.nodes[oldId];delete adventure.editor.nodes[oldId];for(const s of Object.values(scenes())){for(const o of outputsForObjects(s))if(o.next===oldId)o.next=id;}selected=id;});}
  function outputsForObjects(s){const a=[];if(s.type==="scene")for(const c of s.choices||[])a.push(...(c.resolution==="automatic"?[c.outcome]:[c.success,c.failure,c.twist]));if(s.type==="combat")a.push(s.victory,s.defeat);return a.filter(Boolean);}
  function deleteNode(id){if(!confirm(`Delete ${id}?`))return;mutate(()=>{delete scenes()[id];delete adventure.editor?.nodes?.[id];for(const s of Object.values(scenes()))for(const o of outputsForObjects(s))if(o.next===id)delete o.next;if(adventure.startScene===id)adventure.startScene=Object.keys(scenes())[0]||"";selected=null;selectedChoice=null;});}

  function companionReferences(id){
    const refs=[];
    for(const [sceneId,scene] of Object.entries(scenes())){
      if(scene.type==="scene")for(const choice of scene.choices||[]){
        if(choice.actor?.mode==="fixed"&&choice.actor.id===id)refs.push(`${sceneId}/${choice.id}: fixed check actor`);
        if(choice.actor?.mode==="select"&&Array.isArray(choice.actor.eligible)&&choice.actor.eligible.includes(id))refs.push(`${sceneId}/${choice.id}: selectable check actor`);
      }
      if(scene.type==="combat")for(const interaction of scene.interactions||[])for(const effect of interaction.effects||[])if(effect.type==="move-unit"&&effect.side==="pc"&&effect.targetId===id)refs.push(`${sceneId}/${interaction.id}: PC move target`);
    }
    return refs;
  }
  function removeCompanion(index){
    const companion=adventure.party?.[index];if(!companion)return;
    const refs=companionReferences(companion.id);
    if(refs.length){alert(`Cannot remove ${companion.name}. It is still referenced by:\n\n${refs.join("\n")}\n\nChange those references first.`);return;}
    mutate(()=>{
      adventure.party.splice(index,1);
      for(const scene of Object.values(scenes()))if(scene.type==="combat"&&scene.pcStarts)delete scene.pcStarts[companion.id];
    });
  }
  function addCompanionStarts(companionId){
    for(const scene of Object.values(scenes())){
      if(scene.type!=="combat")continue;
      scene.pcStarts ||= {};
      if(scene.pcStarts[companionId])continue;
      const firstZone=scene.battlefield?.zones?.[0]?.id;
      if(firstZone)scene.pcStarts[companionId]=firstZone;
    }
  }
  function acceptCompanionObject(obj){
    const errs=Core?.validateCharacter?Core.validateCharacter(obj):[];
    if(errs.length)throw new Error(errs.join("\n"));
    if((adventure.party||[]).some(p=>p.id===obj.id))throw new Error(`Companion id ${obj.id} is already embedded.`);
    mutate(()=>{adventure.party.push(clone(obj));addCompanionStarts(obj.id);});
  }
  function renderMeta(){inspector.innerHTML=`<h2>Adventure</h2>${field("Adventure ID",adventure.id,"id")}${field("Title",adventure.title,"title")}${field("Quest days",adventure.questDays??0,"questDays","number")}<label class="field"><span>Start scene</span><select id="startScene">${Object.keys(scenes()).map(id=>`<option ${adventure.startScene===id?"selected":""}>${esc(id)}</option>`)}</select></label><div class="section"><div class="section-title"><h3>Required companions</h3><button id="importCompanion" class="mini-btn">Import character JSON</button></div><div class="stack">${(adventure.party||[]).map((p,i)=>`<div class="card"><strong>${esc(p.name)}</strong><div class="muted">${esc(p.id)} · ${esc(p.role)}</div><button data-remove-party="${i}" class="mini-btn danger">Remove</button></div>`).join("")||'<p class="hint">No required companions. $main is still selected by the player.</p>'}</div></div><p class="hint">Imported companions are copied into this adventure. Players do not need the original character file.</p>`;bindFields(inspector,adventure);$("#startScene").onchange=e=>mutate(()=>adventure.startScene=e.target.value);$("#importCompanion").onclick=importCompanion;inspector.querySelectorAll("[data-remove-party]").forEach(b=>b.onclick=()=>removeCompanion(Number(b.dataset.removeParty)));}
  async function importCompanion(){try{if(window.showOpenFilePicker){const [h]=await window.showOpenFilePicker({types:[{description:"Character JSON",accept:{"application/json":[".json"]}}]});acceptCompanionObject(JSON.parse(await (await h.getFile()).text()));}else $("#fallbackCompanion").click();}catch(e){if(e.name!=="AbortError")alert(e.message);}}
  $("#fallbackCompanion").addEventListener("change",async e=>{const f=e.target.files[0];if(!f)return;try{acceptCompanionObject(JSON.parse(await f.text()));}catch(err){alert(err.message)}e.target.value="";});

  function rewriteStatePathReferences(oldPath,newPath){
    function walk(value){
      if(!value||typeof value!=="object")return;
      if(!Array.isArray(value)&&value.path===oldPath)value.path=newPath;
      for(const child of Object.values(value))walk(child);
    }
    walk(adventure.scenes);
  }
  function rewriteClockReferences(oldId,newId){
    for(const scene of Object.values(scenes())){
      if(scene.type==="scene")for(const choice of scene.choices||[]){if(choice.check?.clock===oldId)choice.check.clock=newId;for(const outcome of outputsForObjects(scene))for(const effect of outcome.effects||[])if(effect.type==="advance-clock"&&effect.id===oldId)effect.id=newId;}
      if(scene.type==="combat"){for(const outcome of outputsForObjects(scene))for(const effect of outcome.effects||[])if(effect.type==="advance-clock"&&effect.id===oldId)effect.id=newId;for(const interaction of scene.interactions||[])for(const effect of interaction.effects||[])if(effect.type==="advance-clock"&&effect.id===oldId)effect.id=newId;}
    }
    rewriteStatePathReferences(`clocks.${oldId}.filled`,`clocks.${newId}.filled`);
  }
  function renderState(){
    adventure.initialState ||= {flags:{},counters:{}};adventure.initialState.flags ||= {};adventure.initialState.counters ||= {};adventure.clocks ||= {};
    const entries=(obj,type)=>Object.entries(obj).map(([k,v])=>`<div class="row"><input data-state-key="${type}:${esc(k)}" value="${esc(k)}"><input data-state-val="${type}:${esc(k)}" value="${esc(v)}"></div>`).join("");
    inspector.innerHTML=`<h2>State & Clocks</h2><div class="section"><div class="section-title"><h3>Flags</h3><button class="mini-btn" id="addFlag">+ Flag</button></div>${entries(adventure.initialState.flags,"flag")}</div><div class="section"><div class="section-title"><h3>Counters</h3><button class="mini-btn" id="addCounter">+ Counter</button></div>${entries(adventure.initialState.counters,"counter")}</div><div class="section"><div class="section-title"><h3>Clocks</h3><button class="mini-btn" id="addClock">+ Clock</button></div>${Object.entries(adventure.clocks).map(([id,c])=>`<div class="card"><input data-clock-id="${esc(id)}" value="${esc(id)}"><input data-clock-label="${esc(id)}" value="${esc(c.label)}"><select data-clock-size="${esc(id)}">${[2,4,6].map(n=>`<option ${c.size===n?"selected":""}>${n}</option>`)}</select></div>`).join("")}</div><p class="hint">quest.elapsedDays and clock progress are available to visibility conditions.</p>`;
    $("#addFlag").onclick=()=>mutate(()=>adventure.initialState.flags[unique("flag",new Set(Object.keys(adventure.initialState.flags)))]=false);$("#addCounter").onclick=()=>mutate(()=>adventure.initialState.counters[unique("counter",new Set(Object.keys(adventure.initialState.counters)))]=0);$("#addClock").onclick=()=>mutate(()=>adventure.clocks[unique("clock",new Set(Object.keys(adventure.clocks))) ]={label:"Progress",size:4});
    inspector.querySelectorAll("[data-state-val]").forEach(el=>el.onchange=()=>mutate(()=>{const [t,k]=el.dataset.stateVal.split(":"),raw=el.value,v=raw==="true"?true:raw==="false"?false:(!Number.isNaN(Number(raw))?Number(raw):raw);(t==="flag"?adventure.initialState.flags:adventure.initialState.counters)[k]=v;}));
    inspector.querySelectorAll("[data-state-key]").forEach(el=>el.onchange=()=>{const [t,k]=el.dataset.stateKey.split(":"),obj=t==="flag"?adventure.initialState.flags:adventure.initialState.counters,n=slug(el.value);if(n===k){renderState();return}if(obj[n]!==undefined){alert("That state key already exists.");renderState();return}mutate(()=>{obj[n]=obj[k];delete obj[k];rewriteStatePathReferences(`${t==="flag"?"flags":"counters"}.${k}`,`${t==="flag"?"flags":"counters"}.${n}`);});});
    inspector.querySelectorAll("[data-clock-id]").forEach(el=>el.onchange=()=>{const old=el.dataset.clockId,next=slug(el.value);if(next===old)return;if(adventure.clocks[next]!==undefined){alert("That clock id already exists.");renderState();return}mutate(()=>{adventure.clocks[next]=adventure.clocks[old];delete adventure.clocks[old];rewriteClockReferences(old,next);});});
    inspector.querySelectorAll("[data-clock-label]").forEach(el=>el.onchange=()=>mutate(()=>adventure.clocks[el.dataset.clockLabel].label=el.value));inspector.querySelectorAll("[data-clock-size]").forEach(el=>el.onchange=()=>mutate(()=>adventure.clocks[el.dataset.clockSize].size=Number(el.value)));
  }

  function interactionTargetIssues(){const issues=[];const pcIds=new Set(["$main",...(adventure.party||[]).map(p=>p.id)]);for(const [sceneId,scene] of Object.entries(scenes())){if(scene.type!=="combat")continue;const enemyIds=new Set((scene.enemies||[]).map(e=>e.id));const zoneIds=new Set((scene.battlefield?.zones||[]).map(z=>z.id));for(const interaction of scene.interactions||[])for(const effect of interaction.effects||[]){if((effect.type==="damage-enemy"||effect.type==="condition-enemy")&&!enemyIds.has(effect.targetId)){issues.push({level:"error",text:`${sceneId}/${interaction.id}: ${effect.type} target ${effect.targetId||"(missing)"} is not an authored enemy.`});continue;}if(effect.type!=="move-unit")continue;const validTarget=effect.side==="pc"?pcIds.has(effect.targetId):effect.side==="npc"?enemyIds.has(effect.targetId):false;if(!validTarget)issues.push({level:"error",text:`${sceneId}/${interaction.id}: move-unit target ${effect.targetId||"(missing)"} is not a valid ${effect.side||"unknown"} unit.`});if(!zoneIds.has(effect.zone))issues.push({level:"error",text:`${sceneId}/${interaction.id}: move-unit destination ${effect.zone||"(missing)"} is not an authored zone.`});}}return issues;}
  function authorIssues(){if(!adventure)return[];const issues=[];for(const e of Core?.validateAdventure?.(adventure)||[])issues.push({level:"error",text:e});issues.push(...interactionTargetIssues());const combatIds=Object.entries(scenes()).filter(([,s])=>s.type==="combat").map(([id])=>id);if(combatIds.length>1)issues.push({level:"warning",text:`Adventure contains ${combatIds.length} combats. The game is designed around one substantial combat per adventure.`});if(combatIds.length===0)issues.push({level:"warning",text:"Adventure contains no combat scene."});const endings=Object.entries(scenes()).filter(([,s])=>s.type==="ending").map(([id])=>id);if(!endings.length)issues.push({level:"warning",text:"Adventure contains no ending nodes."});const incoming=new Map(Object.keys(scenes()).map(id=>[id,0]));for(const s of Object.values(scenes()))for(const o of outputsForObjects(s))if(o.next&&incoming.has(o.next))incoming.set(o.next,incoming.get(o.next)+1);for(const [id,n] of incoming)if(id!==adventure.startScene&&n===0)issues.push({level:"info",text:`${id} has no incoming connections.`});const reachable=new Set(),walk=id=>{if(!id||reachable.has(id)||!scenes()[id])return;reachable.add(id);for(const o of outputsForObjects(scenes()[id]))walk(o.next)};walk(adventure.startScene);for(const id of Object.keys(scenes()))if(!reachable.has(id))issues.push({level:"info",text:`${id} is unreachable from the start scene.`});for(const cid of combatIds){const seen=new Set();const dfs=id=>{if(!id||!scenes()[id])return false;if(id===cid)return true;if(seen.has(id))return false;seen.add(id);for(const o of outputsForObjects(scenes()[id]))if(dfs(o.next))return true;return false};for(const o of outputsForObjects(scenes()[cid])){seen.clear();if(dfs(o.next)){issues.push({level:"error",text:`Combat ${cid} can loop back into itself. Combat loops are not supported by the authoring model.`});break;}}}return issues;}
  function renderValidation(){const issues=authorIssues();inspector.innerHTML=`<h2>Validation</h2>${["error","warning","info"].map(level=>`<div class="section"><h3 class="${level}">${level[0].toUpperCase()+level.slice(1)}s</h3>${issues.filter(x=>x.level===level).map(x=>`<div class="validation-item ${level}">${esc(x.text)}</div>`).join("")||'<div class="muted">None.</div>'}</div>`).join("")}<p class="hint">Validation never blocks Save.</p>`;}

  function addNode(type){if(!adventure)return;mutate(()=>{const used=new Set(Object.keys(scenes())),id=unique(type,used),index=used.size;if(type==="scene")scenes()[id]={type:"scene",title:"New Scene",text:["New narration."],choices:[]};if(type==="combat"){const starts=Object.fromEntries(["$main",...(adventure.party||[]).map(p=>p.id)].map(actorId=>[actorId,"zone-1"]));scenes()[id]={type:"combat",title:"New Combat",ambush:false,battlefield:{zones:[{id:"zone-1",name:"Zone 1"}],links:[]},pcStarts:starts,enemies:[],interactions:[],victory:{text:"The party wins.",next:""},defeat:{text:"The party is defeated.",next:""}};}if(type==="ending")scenes()[id]={type:"ending",title:"Ending",outcome:"victory",text:"Write the ending."};ensureEditor();adventure.editor.nodes[id]={x:100+(index%4)*280,y:90+Math.floor(index/4)*180};selected=id;selectedChoice=null;});}

  function openBattlefield(id){battleSceneId=id;battleSelectedZone=null;battleSubEditor=null;renderBattlefield();$("#battlefieldDialog").showModal();}
  function renderBattlefield(){const s=scenes()[battleSceneId],bc=$("#battleCanvas"),be=$("#battleEdges");if(!s)return;bc.innerHTML="";be.innerHTML="";$("#battlefieldTitle").textContent=s.title;s.editor ||= {};s.editor.zones ||= {};const zones=s.battlefield.zones||[];zones.forEach((z,i)=>{const p=s.editor.zones[z.id]||{x:70+(i%4)*240,y:60+Math.floor(i/4)*180};s.editor.zones[z.id]=p;const pcs=Object.entries(s.pcStarts||{}).filter(([,zone])=>zone===z.id).map(([id])=>`<span class="chip">${esc(id)}</span>`).join("");const enemies=(s.enemies||[]).filter(e=>e.zone===z.id).map(e=>`<span class="chip enemy">${esc(e.name)}</span>`).join("");const el=document.createElement("div");el.className=`node zone-node${battleSelectedZone===z.id?" selected":""}`;el.style.left=`${p.x}px`;el.style.top=`${p.y}px`;el.innerHTML=`<div class="node-head"><span>${esc(z.name)}</span><span class="node-id">${esc(z.id)}</span></div><div class="node-body">${pcs}${enemies}</div>`;el.onclick=()=>{battleSelectedZone=z.id;battleSubEditor=null;renderBattlefield()};bc.appendChild(el);});requestAnimationFrame(()=>{for(const l of s.battlefield.links||[]){const za=zones.findIndex(z=>z.id===l.from),zb=zones.findIndex(z=>z.id===l.to);if(za<0||zb<0)continue;const pa=s.editor.zones[l.from],pb=s.editor.zones[l.to],x1=pa.x+180,y1=pa.y+50,x2=pb.x,y2=pb.y+50,path=document.createElementNS("http://www.w3.org/2000/svg","path");path.setAttribute("class","edge");path.setAttribute("d",`M${x1},${y1} C${x1+70},${y1} ${x2-70},${y2} ${x2},${y2}`);be.appendChild(path);}});renderBattleInspector();if(battleSubEditor?.type==="enemy")renderEnemyEditor(battleSubEditor.id,false);if(battleSubEditor?.type==="interaction")renderInteractionEditor(battleSubEditor.id,false);}
  function renameZone(s,z,newRaw){
    const next=slug(newRaw),old=z.id;if(next===old)return old;
    if((s.battlefield.zones||[]).some(other=>other!==z&&other.id===next)){alert("That zone id already exists.");return old;}
    mutateBattle(()=>{
      z.id=next;
      for(const link of s.battlefield.links||[]){if(link.from===old)link.from=next;if(link.to===old)link.to=next;}
      for(const actor of Object.keys(s.pcStarts||{}))if(s.pcStarts[actor]===old)s.pcStarts[actor]=next;
      for(const enemy of s.enemies||[])if(enemy.zone===old)enemy.zone=next;
      for(const interaction of s.interactions||[]){if(interaction.zone===old)interaction.zone=next;for(const effect of interaction.effects||[])if(effect.type==="move-unit"&&effect.zone===old)effect.zone=next;}
      s.editor ||= {};s.editor.zones ||= {};if(s.editor.zones[old]){s.editor.zones[next]=s.editor.zones[old];delete s.editor.zones[old];}
      battleSelectedZone=next;
    });
    return next;
  }
  function renderBattleInspector(){const s=scenes()[battleSceneId],bi=$("#battleInspector");if(battleSelectedZone){const z=s.battlefield.zones.find(x=>x.id===battleSelectedZone);if(!z){battleSelectedZone=null;battleSubEditor=null;return renderBattleInspector();}const zoneLinks=(s.battlefield.links||[]).map((link,index)=>({link,index})).filter(({link})=>link.from===z.id||link.to===z.id);bi.innerHTML=`<h3>Zone</h3>${field("ID",z.id,"id")}${field("Name",z.name,"name")}<button id="addLink" class="mini-btn">Connect to zone…</button><h3>Connections</h3>${zoneLinks.map(({link,index})=>`<div class="card"><div class="card-title"><strong>${esc(link.from)} → ${esc(link.to)}</strong><button data-remove-link="${index}" class="mini-btn danger">Remove</button></div><label class="field"><span>Move cost</span><input data-link-cost="${index}" type="number" min="1" step="1" value="${esc(link.cost??1)}"></label></div>`).join("")||'<p class="hint">No connections from this zone.</p>'}<h3>PC starts</h3>${["$main",...(adventure.party||[]).map(p=>p.id)].map(id=>`<label class="field"><span>${esc(id)}</span><select data-pc-start="${esc(id)}">${s.battlefield.zones.map(q=>`<option value="${esc(q.id)}" ${s.pcStarts?.[id]===q.id?"selected":""}>${esc(q.name)}</option>`)}</select></label>`).join("")}<h3>Enemies here</h3>${(s.enemies||[]).filter(e=>e.zone===z.id).map(e=>`<button data-edit-enemy="${esc(e.id)}">${esc(e.name)}</button>`).join(" ")}<button id="addEnemy" class="mini-btn">+ Enemy</button><h3>Interactions</h3>${(s.interactions||[]).filter(x=>x.zone===z.id).map(x=>`<button data-edit-interaction="${esc(x.id)}">${esc(x.name)}</button>`).join(" ")||'<span class="muted">None.</span>'}<button id="addInteraction" class="mini-btn">+ Interaction</button>`;bi.querySelector('[data-field="id"]').onchange=e=>{const next=renameZone(s,z,e.target.value);battleSelectedZone=next;renderBattlefield();};bi.querySelector('[data-field="name"]').onchange=e=>mutateBattle(()=>z.name=e.target.value);bi.querySelectorAll("[data-pc-start]").forEach(el=>el.onchange=()=>mutateBattle(()=>{s.pcStarts ||= {};s.pcStarts[el.dataset.pcStart]=el.value;}));$("#addLink").onclick=()=>{const target=prompt("Connect to zone id:",s.battlefield.zones.find(q=>q.id!==z.id)?.id||"");if(!target||!s.battlefield.zones.some(q=>q.id===target)||target===z.id)return;const cost=Number(prompt("Move cost:","1"));if(!Number.isInteger(cost)||cost<1){alert("Move cost must be a positive whole number.");return;}mutateBattle(()=>s.battlefield.links.push({from:z.id,to:target,cost}));};bi.querySelectorAll("[data-link-cost]").forEach(el=>el.onchange=()=>{const index=Number(el.dataset.linkCost),cost=Number(el.value);const preview=Model.updateBattlefieldLink(clone(s),index,{cost});if(!preview.ok){alert(preview.error);renderBattlefield();return;}mutateBattle(()=>Model.updateBattlefieldLink(s,index,{cost}));});bi.querySelectorAll("[data-remove-link]").forEach(el=>el.onclick=()=>mutateBattle(()=>Model.removeBattlefieldLink(s,Number(el.dataset.removeLink))));$("#addEnemy").onclick=()=>mutateBattle(()=>{const used=new Set(s.enemies.map(e=>e.id)),id=unique("enemy",used);s.enemies.push({id,name:"New Enemy",preset:"optimal_killer",zone:z.id,hp:100,stamina:10,mana:10,maxAp:2,atk:35,def:5,dodge:30,threat:30,abilities:[{id:"strike",name:"Strike",...clone(ABILITY_TEMPLATES["Weak melee"])}]});});$("#addInteraction").onclick=()=>{let createdId;mutateBattle(()=>{s.interactions ||= [];createdId=unique("interaction",new Set(s.interactions.map(x=>x.id)));s.interactions.push({id:createdId,name:"Interaction",description:"Describe the interaction.",text:"Describe the result.",zone:z.id,ap:1,once:true,effects:[]});});renderInteractionEditor(createdId);};bi.querySelectorAll("[data-edit-enemy]").forEach(b=>b.onclick=()=>renderEnemyEditor(b.dataset.editEnemy));bi.querySelectorAll("[data-edit-interaction]").forEach(b=>b.onclick=()=>renderInteractionEditor(b.dataset.editInteraction));}else bi.innerHTML=`<h3>Battlefield</h3><button id="addZone">+ Zone</button><p class="hint">Select a zone to set starts, enemies, links and interactions.</p>`,$("#addZone").onclick=()=>mutateBattle(()=>{const id=unique("zone",new Set(s.battlefield.zones.map(z=>z.id)));s.battlefield.zones.push({id,name:"New Zone"});});}
  function mutateBattle(fn){checkpoint();fn();render();renderBattlefield();}
  function renameEnemy(s,e,newRaw){
    const next=slug(newRaw),old=e.id;if(next===old)return old;
    if((s.enemies||[]).some(other=>other!==e&&other.id===next)){alert("That enemy id already exists.");return old;}
    battleSubEditor={type:"enemy",id:next};
    mutateBattle(()=>{e.id=next;for(const interaction of s.interactions||[])for(const effect of interaction.effects||[]){if(effect.targetId!==old)continue;if(effect.type==="damage-enemy"||effect.type==="condition-enemy"||(effect.type==="move-unit"&&effect.side==="npc"))effect.targetId=next;}});
    return next;
  }
  function deleteEnemy(s,e){
    const id=e.id;battleSubEditor=null;
    mutateBattle(()=>{
      s.enemies.splice(s.enemies.indexOf(e),1);
      for(const interaction of s.interactions||[])interaction.effects=(interaction.effects||[]).filter(effect=>!(effect.targetId===id&&(effect.type==="damage-enemy"||effect.type==="condition-enemy"||(effect.type==="move-unit"&&effect.side==="npc"))));
    });
  }
  function abilityEditor(a,i){
    const tags=(a.tags||[]).join(", ");
    return `<div class="card"><div class="card-title"><strong>${esc(a.name)}</strong><button data-del-ability="${i}">×</button></div><div class="row three"><input data-ab-id="${i}" value="${esc(a.id)}" placeholder="Ability ID"><input data-ab-name="${i}" value="${esc(a.name)}" placeholder="Name"><select data-ab-kind="${i}">${ABILITY_KINDS.map(kind=>`<option value="${kind}" ${a.kind===kind?"selected":""}>${kind}</option>`)}</select></div><div class="row three"><label class="field"><span>AP</span><input data-ab-ap="${i}" type="number" value="${esc(a.ap??1)}"></label><label class="field"><span>Stamina</span><input data-ab-stamina="${i}" type="number" value="${esc(a.stamina??0)}"></label><label class="field"><span>Mana</span><input data-ab-mana="${i}" type="number" value="${esc(a.mana??0)}"></label></div><div class="row three"><label class="field"><span>Power</span><input data-ab-power="${i}" type="number" value="${esc(a.power??0)}"></label><label class="field"><span>Min range</span><input data-ab-min-range="${i}" type="number" value="${esc(a.minRange??0)}"></label><label class="field"><span>Max range</span><input data-ab-max-range="${i}" type="number" value="${esc(a.maxRange??0)}"></label></div><div class="row"><label class="field"><span>Attack bonus</span><input data-ab-attack-bonus="${i}" type="number" value="${esc(a.attackBonus??0)}"></label><label class="field"><span>Tags</span><input data-ab-tags="${i}" value="${esc(tags)}" placeholder="Physical, Magical"></label></div>${Model.abilityUsesTargetBounds(a.kind)?`<div class="row"><label class="field"><span>Min targets</span><input data-ab-min-targets="${i}" type="number" value="${esc(a.minTargets??2)}"></label><label class="field"><span>Max targets</span><input data-ab-max-targets="${i}" type="number" value="${esc(a.maxTargets??3)}"></label></div>`:""}${a.kind==="persistent"?`<div class="row three"><input data-ab-condition-id="${i}" value="${esc(a.condition?.id||"Persistent Damage")}" placeholder="Condition"><input data-ab-condition-amount="${i}" type="number" value="${esc(a.condition?.amount??0)}" placeholder="Amount"><input data-ab-condition-expression="${i}" value="${esc(a.condition?.expression||"")}" placeholder="Expression"></div>`:""}</div>`;
  }
  function renderEnemyEditor(id,setActive=true){
    const s=scenes()[battleSceneId],e=s.enemies.find(x=>x.id===id),bi=$("#battleInspector");if(!e){battleSubEditor=null;return renderBattleInspector();}if(setActive)battleSubEditor={type:"enemy",id:e.id};e.abilities ||= [];
    bi.innerHTML=`<button id="backZone">← Zone</button><h3>Enemy</h3>${field("ID",e.id,"id")}${field("Name",e.name,"name")}<label class="field"><span>Starting zone</span><select id="enemyZone">${(s.battlefield.zones||[]).map(z=>`<option value="${esc(z.id)}" ${e.zone===z.id?"selected":""}>${esc(z.name)}</option>`)}</select></label><label class="field"><span>AI preset</span><select id="enemyPreset">${PRESETS.map(p=>`<option ${e.preset===p?"selected":""}>${p}</option>`)}</select></label><div class="row three">${field("HP",e.hp,"hp","number")}${field("Stamina",e.stamina??0,"stamina","number")}${field("Mana",e.mana??0,"mana","number")}${field("AP",e.maxAp,"maxAp","number")}${field("ATK",e.atk,"atk","number")}${field("DEF",e.def,"def","number")}${field("Dodge",e.dodge,"dodge","number")}${field("Threat",e.threat,"threat","number")}</div><div class="section"><h3>Abilities</h3>${e.abilities.map(abilityEditor).join("")}<label class="field"><span>Add ability template</span><select id="abilityTemplate">${Object.keys(ABILITY_TEMPLATES).map(k=>`<option>${esc(k)}</option>`)}</select></label><button id="addAbility" class="mini-btn">Add ability</button></div><div class="inline"><button id="duplicateEnemy">Duplicate ×…</button><button id="deleteEnemy" class="danger">Delete</button></div>`;
    $("#backZone").onclick=()=>{battleSubEditor=null;renderBattleInspector();};
    const keep=fn=>{battleSubEditor={type:"enemy",id:e.id};mutateBattle(fn);};
    bi.querySelector('[data-field="id"]').onchange=x=>{const next=renameEnemy(s,e,x.target.value);battleSubEditor={type:"enemy",id:next};};
    bi.querySelector('[data-field="name"]').onchange=x=>keep(()=>e.name=x.target.value);for(const key of ["hp","stamina","mana","maxAp","atk","def","dodge","threat"])bi.querySelector(`[data-field="${key}"]`).onchange=x=>keep(()=>e[key]=Number(x.target.value));$("#enemyZone").onchange=x=>keep(()=>e.zone=x.target.value);$("#enemyPreset").onchange=x=>keep(()=>e.preset=x.target.value);
    const numeric=(selector,key)=>bi.querySelectorAll(selector).forEach(x=>x.onchange=()=>keep(()=>e.abilities[Number(Object.values(x.dataset)[0])][key]=Number(x.value)));
    bi.querySelectorAll("[data-ab-id]").forEach(x=>x.onchange=()=>keep(()=>{const i=Number(x.dataset.abId),a=e.abilities[i],next=slug(x.value);if(e.abilities.some((other,j)=>j!==i&&other.id===next)){alert("That ability id already exists on this enemy.");return}a.id=next;}));
    bi.querySelectorAll("[data-ab-name]").forEach(x=>x.onchange=()=>keep(()=>e.abilities[Number(x.dataset.abName)].name=x.value));
    bi.querySelectorAll("[data-ab-kind]").forEach(x=>x.onchange=()=>keep(()=>{const a=e.abilities[Number(x.dataset.abKind)];a.kind=x.value;Model.ensureAbilityKindFields(a);}));
    numeric("[data-ab-ap]","ap");numeric("[data-ab-stamina]","stamina");numeric("[data-ab-mana]","mana");numeric("[data-ab-power]","power");numeric("[data-ab-min-range]","minRange");numeric("[data-ab-max-range]","maxRange");numeric("[data-ab-attack-bonus]","attackBonus");numeric("[data-ab-min-targets]","minTargets");numeric("[data-ab-max-targets]","maxTargets");
    bi.querySelectorAll("[data-ab-tags]").forEach(x=>x.onchange=()=>keep(()=>e.abilities[Number(x.dataset.abTags)].tags=x.value.split(",").map(v=>v.trim()).filter(Boolean)));
    bi.querySelectorAll("[data-ab-condition-id]").forEach(x=>x.onchange=()=>keep(()=>{const a=e.abilities[Number(x.dataset.abConditionId)];a.condition ||= {};a.condition.id=x.value;}));
    bi.querySelectorAll("[data-ab-condition-amount]").forEach(x=>x.onchange=()=>keep(()=>{const a=e.abilities[Number(x.dataset.abConditionAmount)];a.condition ||= {};a.condition.amount=Number(x.value);}));
    bi.querySelectorAll("[data-ab-condition-expression]").forEach(x=>x.onchange=()=>keep(()=>{const a=e.abilities[Number(x.dataset.abConditionExpression)];a.condition ||= {};a.condition.expression=x.value;}));
    bi.querySelectorAll("[data-del-ability]").forEach(x=>x.onclick=()=>keep(()=>e.abilities.splice(Number(x.dataset.delAbility),1)));
    $("#addAbility").onclick=()=>keep(()=>{const label=$("#abilityTemplate").value,t=clone(ABILITY_TEMPLATES[label]),aid=unique(slug(label),new Set(e.abilities.map(a=>a.id)));e.abilities.push({id:aid,name:label,...t});});
    $("#duplicateEnemy").onclick=()=>{const n=Math.max(1,Number(prompt("How many copies?","5"))||1);battleSubEditor={type:"enemy",id:e.id};mutateBattle(()=>{const used=new Set(s.enemies.map(x=>x.id));for(let i=0;i<n;i++){const copy=clone(e);copy.id=unique(e.id,used);used.add(copy.id);copy.name=`${e.name} ${i+2}`;s.enemies.push(copy);}});};$("#deleteEnemy").onclick=()=>deleteEnemy(s,e);
  }

  function interactionEffectFields(effect,index,s){
    const enemyOptions=(s.enemies||[]).map(e=>`<option value="${esc(e.id)}" ${effect.targetId===e.id?"selected":""}>${esc(e.name)}</option>`).join("");
    const pcOptions=[{id:"$main",name:"$main"},...(adventure.party||[]).map(p=>({id:p.id,name:p.name}))].map(p=>`<option value="${esc(p.id)}" ${effect.targetId===p.id?"selected":""}>${esc(p.name)}</option>`).join("");
    const zoneOptions=(s.battlefield.zones||[]).map(z=>`<option value="${esc(z.id)}" ${effect.zone===z.id?"selected":""}>${esc(z.name)}</option>`).join("");
    if(effect.type==="set")return `<select data-ie-path="${index}">${statePaths().map(p=>`<option ${effect.path===p?"selected":""}>${esc(p)}</option>`)}</select><input data-ie-value="${index}" value="${esc(effect.value??"")}">`;
    if(effect.type==="add")return `<select data-ie-path="${index}">${statePaths().map(p=>`<option ${effect.path===p?"selected":""}>${esc(p)}</option>`)}</select><input data-ie-value="${index}" type="number" step="any" value="${esc(effect.value??0)}">`;
    if(effect.type==="advance-clock")return `<select data-ie-clock="${index}">${Object.keys(adventure.clocks||{}).map(id=>`<option ${effect.id===id?"selected":""}>${esc(id)}</option>`)}</select><input data-ie-segments="${index}" type="number" value="${esc(effect.segments??1)}">`;
    if(effect.type==="damage-enemy")return `<select data-ie-target="${index}">${enemyOptions}</select><input data-ie-amount="${index}" type="number" value="${esc(effect.amount??0)}">`;
    if(effect.type==="condition-enemy")return `<select data-ie-target="${index}">${enemyOptions}</select><input data-ie-condition="${index}" value="${esc(effect.condition?.id||"Persistent Damage")}" placeholder="Condition"><input data-ie-condition-amount="${index}" type="number" value="${esc(effect.condition?.amount??0)}" placeholder="Amount"><input data-ie-expression="${index}" value="${esc(effect.condition?.expression||"")}" placeholder="Expression">`;
    if(effect.type==="move-unit")return `<select data-ie-side="${index}"><option value="pc" ${effect.side==="pc"?"selected":""}>pc</option><option value="npc" ${effect.side==="npc"?"selected":""}>npc</option></select><select data-ie-unit="${index}">${effect.side==="pc"?pcOptions:enemyOptions}</select><select data-ie-zone="${index}">${zoneOptions}</select>`;
    return "";
  }
  function renderInteractionEditor(id,setActive=true){
    const s=scenes()[battleSceneId],interaction=(s.interactions||[]).find(x=>x.id===id),bi=$("#battleInspector");if(!interaction){battleSubEditor=null;return renderBattleInspector();}if(setActive)battleSubEditor={type:"interaction",id:interaction.id};interaction.effects ||= [];
    const types=["set","add","advance-clock","damage-enemy","condition-enemy","move-unit"];
    bi.innerHTML=`<button id="backZone">← Zone</button><h3>Interaction</h3>${field("ID",interaction.id,"id")}${field("Name",interaction.name,"name")}<label class="field"><span>Description</span><textarea id="interactionDescription">${esc(interaction.description||"")}</textarea></label><label class="field"><span>Result text</span><textarea id="interactionText">${esc(interaction.text||"")}</textarea></label>${field("AP cost",interaction.ap??1,"ap","number")}<label class="field"><span>Usage</span><select id="interactionOnce"><option value="true" ${interaction.once!==false?"selected":""}>Once</option><option value="false" ${interaction.once===false?"selected":""}>Repeatable</option></select></label><div class="section"><div class="section-title"><h3>Effects</h3><button id="addInteractionEffect" class="mini-btn">+ Effect</button></div>${interaction.effects.map((effect,i)=>`<div class="card"><select data-ie-type="${i}">${types.map(type=>`<option value="${type}" ${effect.type===type?"selected":""}>${type}</option>`)}</select><div class="stack">${interactionEffectFields(effect,i,s)}</div><button data-ie-remove="${i}" class="mini-btn danger">Remove</button></div>`).join("")||'<p class="hint">No effects yet.</p>'}</div><button id="deleteInteraction" class="danger">Delete interaction</button>`;
    $("#backZone").onclick=()=>{battleSubEditor=null;renderBattleInspector();};
    const keep=fn=>{battleSubEditor={type:"interaction",id:interaction.id};mutateBattle(fn);};
    bi.querySelector('[data-field="id"]').onchange=e=>{const next=slug(e.target.value);if(next===interaction.id)return;if((s.interactions||[]).some(x=>x!==interaction&&x.id===next)){alert("That interaction id already exists.");return renderInteractionEditor(interaction.id);}battleSubEditor={type:"interaction",id:next};mutateBattle(()=>interaction.id=next);};
    bi.querySelector('[data-field="name"]').onchange=e=>keep(()=>interaction.name=e.target.value);bi.querySelector('[data-field="ap"]').onchange=e=>keep(()=>interaction.ap=Number(e.target.value));$("#interactionDescription").onchange=e=>keep(()=>interaction.description=e.target.value);$("#interactionText").onchange=e=>keep(()=>interaction.text=e.target.value);$("#interactionOnce").onchange=e=>keep(()=>interaction.once=e.target.value==="true");
    $("#addInteractionEffect").onclick=()=>keep(()=>interaction.effects.push({type:"set",path:statePaths()[0]||"quest.elapsedDays",value:true}));
    bi.querySelectorAll("[data-ie-remove]").forEach(el=>el.onclick=()=>keep(()=>interaction.effects.splice(Number(el.dataset.ieRemove),1)));
    bi.querySelectorAll("[data-ie-type]").forEach(el=>el.onchange=()=>{const i=Number(el.dataset.ieType),type=el.value;keep(()=>{if(type==="set")interaction.effects[i]={type,path:statePaths()[0]||"quest.elapsedDays",value:true};if(type==="add")interaction.effects[i]={type,path:statePaths()[0]||"quest.elapsedDays",value:1};if(type==="advance-clock")interaction.effects[i]={type,id:Object.keys(adventure.clocks||{})[0]||"clock",segments:1};if(type==="damage-enemy")interaction.effects[i]={type,targetId:s.enemies?.[0]?.id||"enemy",amount:10};if(type==="condition-enemy")interaction.effects[i]={type,targetId:s.enemies?.[0]?.id||"enemy",condition:{id:"Persistent Damage",amount:10,expression:"Burning"}};if(type==="move-unit")interaction.effects[i]={type,side:"npc",targetId:s.enemies?.[0]?.id||"",zone:s.battlefield.zones?.[0]?.id||"zone"};});});
    const change=(selector,fn)=>bi.querySelectorAll(selector).forEach(el=>el.onchange=()=>keep(()=>fn(interaction.effects[Number(Object.values(el.dataset)[0])],el)));
    change("[data-ie-path]",(ef,el)=>ef.path=el.value);bi.querySelectorAll("[data-ie-value]").forEach(el=>el.onchange=()=>{const i=Number(el.dataset.ieValue),ef=interaction.effects[i];if(ef.type==="add"){const parsed=Model.parseAddEffectValue(el.value);if(!parsed.ok){alert(parsed.error);renderInteractionEditor(interaction.id);return;}keep(()=>interaction.effects[i].value=parsed.value);return;}const raw=el.value;keep(()=>interaction.effects[i].value=raw==="true"?true:raw==="false"?false:(raw!==""&&!Number.isNaN(Number(raw))?Number(raw):raw));});change("[data-ie-clock]",(ef,el)=>ef.id=el.value);change("[data-ie-segments]",(ef,el)=>ef.segments=Number(el.value));change("[data-ie-target]",(ef,el)=>ef.targetId=el.value);change("[data-ie-amount]",(ef,el)=>ef.amount=Number(el.value));change("[data-ie-condition]",(ef,el)=>{ef.condition ||= {};ef.condition.id=el.value;});change("[data-ie-condition-amount]",(ef,el)=>{ef.condition ||= {};ef.condition.amount=Number(el.value);});change("[data-ie-expression]",(ef,el)=>{ef.condition ||= {};ef.condition.expression=el.value;});change("[data-ie-side]",(ef,el)=>{ef.side=el.value;ef.targetId=el.value==="pc"?"$main":s.enemies?.[0]?.id||"";});change("[data-ie-unit]",(ef,el)=>ef.targetId=el.value);change("[data-ie-zone]",(ef,el)=>ef.zone=el.value);
    $("#deleteInteraction").onclick=()=>{battleSubEditor=null;mutateBattle(()=>s.interactions.splice(s.interactions.indexOf(interaction),1));};
  }

  function render(){fileLabel.textContent=adventure?(fileHandle?`${adventure.id}.json`:adventure.title):"Untitled";renderGraph();renderInspector();}

  $("#newBtn").onclick=()=>$("#wizardDialog").showModal();$("#createAdventureBtn").onclick=e=>{e.preventDefault();const form=$("#wizardForm");if(!form.reportValidity())return;const id=$("#wizId").value,title=$("#wizTitle").value,days=$("#wizDays").value,errors=Model.validateWizardDraftInput(id,title,days);if(errors.length){alert(errors.join("\n"));return;}newAdventure(id,title,days);$("#wizardDialog").close();};$("#openBtn").onclick=openFile;$("#saveBtn").onclick=saveFile;$("#undoBtn").onclick=undo;$("#redoBtn").onclick=redo;$("#metaBtn").onclick=()=>{selected=null;selectedChoice=null;renderMeta()};$("#stateBtn").onclick=()=>{selected=null;selectedChoice=null;renderState()};$("#validateBtn").onclick=()=>{selected=null;selectedChoice=null;renderValidation()};document.querySelectorAll("[data-add]").forEach(b=>b.onclick=()=>addNode(b.dataset.add));canvas.onclick=()=>{selected=null;selectedChoice=null;render()};$("#jsonBtn").onclick=()=>{if(!adventure)return;$("#jsonText").value=JSON.stringify(adventure,null,2);$("#jsonError").textContent="";$("#jsonDialog").showModal();};$("#applyJsonBtn").onclick=e=>{e.preventDefault();try{const obj=JSON.parse($("#jsonText").value);assertOpenable(obj);checkpoint();adventure=obj;normalizeLayout();selected=null;selectedChoice=null;battleSubEditor=null;$("#jsonDialog").close();render();}catch(err){$("#jsonError").textContent=err.message;}};$("#closeBattlefieldBtn").onclick=()=>{battleSubEditor=null;$("#battlefieldDialog").close();};document.addEventListener("keydown",e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==="z"){e.preventDefault();e.shiftKey?redo():undo()}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==="y"){e.preventDefault();redo()}});

  resetHistory(); render();
})();